// Every engine call goes through callTool: a timeout the mod API does not give us, result parsing
// that copes with the payload arriving as JSON text (spec 2.2), and one outcome type the hooks
// branch on.

/** The part of $.mcp.call's result this module reads. */
export interface RawResult {
  content: ReadonlyArray<{ type: string; text?: string }>
  isError: boolean
  structuredContent?: unknown
}

export interface McpDeps {
  call: (server: string, tool: string, args: Record<string, unknown>) => Promise<RawResult>
  /** $.clock.sleep: the one wait that counts against the hook budget. */
  sleep: (ms: number) => Promise<void>
  now: () => Promise<number>
}

export type CallOutcome =
  | { kind: 'ok'; data: unknown; text: string; ms: number }
  /** The engine answered with isError: a validation or conflict message in `text`. */
  | { kind: 'tool_error'; text: string; ms: number }
  | { kind: 'timeout'; ms: number }
  /** The call threw: no server by that name, connection refused, transport failure. */
  | { kind: 'unreachable'; error: string; ms: number }
  /** The permission chain refused the call ("haven't granted it", "denied"). */
  | { kind: 'denied'; error: string; ms: number }
  /** The server is not (yet) connected, absent, or has its tools removed by the user's settings. */
  | { kind: 'not_connected'; error: string; ms: number }

/**
 * structuredContent when present; else the first text block parsed as JSON; else `data` is the
 * raw text (an engine that answers markdown). `text` is always the first text block, or "".
 */
export function parseResult(raw: RawResult): { isError: boolean; data: unknown; text: string } {
  const block = raw.content.find((b) => b.type === 'text' && typeof b.text === 'string')
  const text = block?.text ?? ''
  if (raw.structuredContent !== undefined && raw.structuredContent !== null) {
    return { isError: raw.isError, data: raw.structuredContent, text }
  }
  try {
    return { isError: raw.isError, data: JSON.parse(text), text }
  } catch {
    return { isError: raw.isError, data: text, text }
  }
}

/**
 * Claude Code 2.1.287 throws this while MCP servers are still connecting, and for a server the
 * user never configured or whose tools their settings disallow (a disallowed tool leaves the
 * engine): `no tool "context_bootstrap" on a server named "lumberroom"; servers with tools: ...`.
 */
const NOT_CONNECTED = [/no (connected )?(mcp )?tool "[^"]+" on a server named/i, /no (mcp )?server (found )?(named|with name)/i]

/** A thrown error from $.mcp.call: a permission refusal, a server that is not connected, or an outage. */
export function classifyError(err: unknown): 'denied' | 'unreachable' | 'not_connected' {
  const msg = err instanceof Error ? err.message : String(err ?? '')
  // `$.mcp.call(server, tool) refused: <reason>` is Claude Code's wording for a permission refusal.
  if (/permission|haven'?t granted|denied|\) refused: /i.test(msg)) return 'denied'
  return NOT_CONNECTED.some((re) => re.test(msg)) ? 'not_connected' : 'unreachable'
}

/**
 * Races deps.call against deps.sleep(timeoutMs). The losing call keeps running and its result,
 * or its rejection, is swallowed. `ms` is measured with deps.now.
 */
export async function callTool(
  deps: McpDeps,
  server: string,
  tool: string,
  args: Record<string, unknown>,
  timeoutMs: number,
): Promise<CallOutcome> {
  const start = await deps.now()
  type Settled = { r: RawResult } | { e: unknown } | { timeout: true }
  // Both arms resolve, never reject, so the losing call cannot raise an unhandled rejection later.
  const call: Promise<Settled> = (async () => deps.call(server, tool, args))().then(
    (r) => ({ r }),
    (e: unknown) => ({ e }),
  )
  const timer: Promise<Settled> = deps.sleep(timeoutMs).then(() => ({ timeout: true as const }))
  const won = await Promise.race([call, timer])
  const ms = (await deps.now()) - start
  if ('timeout' in won) return { kind: 'timeout', ms }
  if ('e' in won) {
    const error = won.e instanceof Error ? won.e.message : String(won.e)
    return { kind: classifyError(won.e), error, ms }
  }
  const parsed = parseResult(won.r)
  if (parsed.isError) return { kind: 'tool_error', text: parsed.text, ms }
  return { kind: 'ok', data: parsed.data, text: parsed.text, ms }
}

/** True for the outcomes that count as an outage: the breaker records them. */
export function isOutage(outcome: CallOutcome): boolean {
  return outcome.kind === 'timeout' || outcome.kind === 'unreachable'
}

files.src/race.ts:
// A bound on work that takes no signal. $.clock.sleep is the only wait a hook can use, so it is the
// timer. The slower arm keeps running; its result, or its rejection, is dropped.

export type Raced<T> = { timedOut: false; value: T } | { timedOut: true }

/**
 * Resolves with `work`'s value, or `{ timedOut: true }` once `sleep(ms)` finishes first. A
 * rejection from `work` before the timer propagates; one after it is swallowed.
 */
export async function raceSleep<T>(work: Promise<T>, sleep: (ms: number) => Promise<void>, ms: number): Promise<Raced<T>> {
  type Settled = { r: T } | { e: unknown } | { timeout: true }
  const arm: Promise<Settled> = work.then(
    (r) => ({ r }),
    (e: unknown) => ({ e }),
  )
  const timer: Promise<Settled> = sleep(ms).then(() => ({ timeout: true as const }))
  const won = await Promise.race([arm, timer])
  if ('timeout' in won) return { timedOut: true }
  if ('e' in won) throw won.e
  return { timedOut: false, value: won.r }
}

files.src/server.ts:
// Which MCP server the plugin talks to. The plugin ships its own server in .mcp.json, which Claude
// Code registers as `plugin:<plugin>:<name>` and suppresses when a server the person registered
// points at the same URL, or a claude.ai connector does. $.mcp.connect on the bundled key answers
// with whichever name the session runs the server under; the list below is the fallback when it
// cannot answer. So the plugin tries the bundled one first and falls back to a registered
// `lumberroom`: the same install works before and after the person removes their own entry, and a
// self-hosted engine registered as `lumberroom` works with no plugin option.

import { OWN_PLUGIN } from './own'

/** The server's key in .mcp.json, which $.mcp.connect takes. */
export const BUNDLED_KEY = 'lumberroom'
export const BUNDLED_SERVER = `plugin:${OWN_PLUGIN}:${BUNDLED_KEY}`
export const REGISTERED_SERVER = 'lumberroom'

export const SERVER_CANDIDATES: readonly [string, ...string[]] = [BUNDLED_SERVER, REGISTERED_SERVER]

/** The prefix of a server's tools as Claude Code spells it: `plugin:a:b` becomes `mcp__plugin_a_b__`. */
export function toolPrefix(server: string): string {
  return `mcp__${server.replace(/[^a-zA-Z0-9_-]/g, '_')}__`
}

files.src/credential.ts:
// Where /lr-import sends memory files and which bearer it carries. The lumberroom CLI already holds
// both: `lumberroom login` writes an OAuth token and the engine URL to its config file, so a person
// who uses the CLI configures nothing here. The order mirrors the CLI's own `resolve` in
// crates/lumberroom/src/config.rs (environment beats file, a static token beats an OAuth one), with
// the plugin's ingestToken option in front of all of them.

/** The engine the bundled MCP server talks to, without /mcp. */
export const DEFAULT_ENGINE = 'https://mcp.lumberroom.cloud'

export type IngestSource = 'option' | 'env' | 'cli-token' | 'cli-oauth'

export interface IngestCredential {
  /** Engine base URL without a trailing slash or /mcp. */
  baseUrl: string
  token: string
  source: IngestSource
}

export interface IngestInputs {
  /** The ingestToken option, already trimmed; undefined when unset. */
  optionToken?: string
  /** LUMBERROOM_URL and LUMBERROOM_TOKEN from the environment. */
  envUrl?: string
  envToken?: string
  /** The CLI config file's text, '' when absent or unreadable. */
  cliConfig: string
  /** Milliseconds since the epoch. */
  now: number
}

export type IngestResolution = { ok: true; credential: IngestCredential } | { ok: false; reason: 'none' | 'expired' }

/** The CLI's config path: LUMBERROOM_CONFIG, else ~/.config/lumberroom/config.json. */
export function cliConfigPath(envConfig: string | undefined, home: string): string {
  const set = envConfig?.trim() ?? ''
  return set !== '' ? set : `${home}/.config/lumberroom/config.json`
}

/** A URL the CLI accepts (base or .../mcp) -> the engine base the /admin routes hang off. */
export function engineBase(url: string): string {
  return url.trim().replace(/\/+$/, '').replace(/\/mcp$/, '')
}

const field = (obj: unknown, key: string): string => {
  if (typeof obj !== 'object' || obj === null) return ''
  const v = (obj as Record<string, unknown>)[key]
  return typeof v === 'string' ? v.trim() : ''
}

/** Never throws. An empty value counts as unset at every step, as in the CLI. */
export function resolveIngest(inputs: IngestInputs): IngestResolution {
  let file: unknown = {}
  try {
    file = JSON.parse(inputs.cliConfig)
  } catch {
    file = {}
  }
  const oauth = typeof file === 'object' && file !== null ? (file as Record<string, unknown>).oauth : undefined

  const url = [inputs.envUrl?.trim() ?? '', field(file, 'url')].find((u) => u !== '') ?? DEFAULT_ENGINE
  const baseUrl = engineBase(url)

  const statics: [string, IngestSource][] = [
    [inputs.optionToken?.trim() ?? '', 'option'],
    [inputs.envToken?.trim() ?? '', 'env'],
    [field(file, 'token'), 'cli-token'],
  ]
  for (const [token, source] of statics) if (token !== '') return { ok: true, credential: { baseUrl, token, source } }

  const access = field(oauth, 'access_token')
  if (access === '') return { ok: false, reason: 'none' }
  // The CLI refreshes on its next request, so an expired token means "run any lumberroom command".
  const expires = Date.parse(field(oauth, 'expires_at'))
  if (Number.isFinite(expires) && expires <= inputs.now) return { ok: false, reason: 'expired' }
  return { ok: true, credential: { baseUrl, token: access, source: 'cli-oauth' } }
}

